window.SAQ_PAPER_QUESTIONS["2015-1-tpch"]=[{"number":1,"title":"","stemText":"You are the consultant on duty and you have taken over the care of a 23 year old woman who has been intubated and ventilated for a polypharmacy overdose.\nHer vital signs post intubation are:\n\nHR\n130\n\nBP\n100/70\n\nSats\n92% on 50%\n\nRR\n\nTemp\n35.6 ETCO2 Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 6 possible causes for her tachycardia and describe one distinguishing historical\nfeature for each (12 marks) Possible causes Historical features any way without previous permission 2- Your Ventilator settings are as follows : Volume control ventilation:\nTV 280\nRate 16\nPEEP 5"},{"id":"b","label":"Part B","prompt":"E ratio 1:3\nList 2 unsatisfactory parameters with her ventilation and suggest 2 changes you would\nmake to these settings to improve her ventilation. (6 marks) Ventilation Changes suggested parameters"},{"id":"c","label":"Part C","prompt":"Give 4 reasons (unrelated to her ventilator settings) why her ETCO2 may be high and\ngive one example of each. (8 marks) any way without previous permission"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>feature for each</td><td>(12 marks) 8/12</td></tr><tr><td>Answer 1</td><td></td></tr><tr><td>1) Toxidromes - Anticholinergic toxidrome :Empty packets of antihistamines,</td><td></td></tr><tr><td>TCAs etc, /other features dry, hot, urinary retention etc</td><td></td></tr><tr><td>Sympothomimetic toxidrome : Hx of IVDU or theophylene,/ hx tremor</td><td></td></tr><tr><td>agitation and convulsions</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">taking SSRIs or TCA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">bleeding</div><div class=\"answer-line\">4) Hypoglycaemia : sweaty, poor eating or /hypoglycaemic overdose</div><div class=\"answer-line\">5) Hypoxia : difficult ventilation, intubation/ ALOC</div><div class=\"answer-line\">6) Lack of sedation post intubation</div><div class=\"answer-line\">7) Sepsis – IVDU, recent infections</div><div class=\"answer-line\">2- Your Ventilator settings are as follows :</div><div class=\"answer-line\">Volume control ventilation:</div><div class=\"answer-line\">TV 280</div><div class=\"answer-line\">Rate 16</div><div class=\"answer-line\">PEEP 5</div><div class=\"answer-line\">I:E ratio 1:3</div><div class=\"answer-line\">List 2 unsatisfactory parameters with her ventilation and suggest 2 changes you would</div><div class=\"answer-line\">make to these settings to improve her ventilation.</div><div class=\"answer-line\">(6 marks)  - 5/6</div><div class=\"answer-line\">Answer 2</div><div class=\"answer-line\"><strong>Hypoxia</strong> therefore increase TV to 6-8ml/kg likely &gt;300, Increase I: E ratio to 1:4</div><div class=\"answer-line\">or increase FiO2 to 60% or increase PEEP to 6-8 (ensure Peak pressures</div><div class=\"answer-line\">&lt;30)aim Sats &gt; 93%</div><div class=\"answer-line\"><strong>Hypercarbia</strong> therefore increase TV to 6-8ml/kg or Rate 18-20 Aim PCO2 &lt;40</div><div class=\"answer-line\">3. Give 4 reasons (unrelated to her ventilator settings) why her ETCO2 may be high and</div><div class=\"answer-line\">give one example of each. (8 marks)  - 5/8</div><div class=\"answer-line\"><strong>any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div><div class=\"answer-line\">Answer 3</div><div class=\"answer-line\">1) Increased CO2 production – fever, thyrotoxicosis</div><div class=\"answer-line\">2) Increased pulmonary perfusion – High CO, hypertension</div><div class=\"answer-line\">3) Poor alveolar ventilation – hypoventilation, bronchial intubation</div><div class=\"answer-line\">4) Technical mechanical errors – leak or faulty valve</div><div class=\"answer-line\"><strong>Passmark 18/26  (adjust to /10)  (7/10) </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 30 year old female presents to ED with intermittent Chest pain for 2 days. She has\npain with deep inspiration. She has no other associated symptoms. She has been well until this illness. She has no known medical conditions.\nHer vital signs are:\n\nGCS\n15/15\n\nBP\n110/77\n\nRR\n\nSpO2\n97% in room air The patient’s ECG is reproduced. any way without previous permission any way without previous permission","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities on the ECG. (3 marks)"},{"id":"b","label":"Part B","prompt":"What is your provisional likely diagnosis? Justify your choice. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 additional investigations that are indicated to further assess the extent and\nseverity of this condition. (3 marks) any way without previous permission"},{"id":"d","label":"Part D","prompt":"In the table below, list the possible underlying aetiological processes causing this patients condition. Give 1 example of each and list the relevant investigation that could be ordered. (12 marks)"}],"propPages":["asset:imgd301796b1aeb0a342b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">PR depression I , II, V5,  V6 (PR elevation in aVR)</div><div class=\"answer-line\">Diffuse ST elevation I, II and Chest leads</div><div class=\"answer-line\">No geographical distribution - no reciprocation</div><div class=\"answer-line\">(Except avr)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute pericarditis</div><div class=\"answer-line\">Nature of pain - age young - no obvious risks for pe.</div><div class=\"answer-line\">ECG pathognomonic</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Troponin/CK</div><div class=\"answer-line\">Echo</div><div class=\"answer-line\">MRI</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Infectious</div><div class=\"answer-line\">Viral - usually no testing needed, PCR, serology</div><div class=\"answer-line\">Bacterial - bc if patient febrile</div><div class=\"answer-line\">Tb - if contact history or from high risk group - mantoux  cxr</div><div class=\"answer-line\">Inflammatory</div><div class=\"answer-line\">SLE / rheumatoid - if other symptoms or family history and no other cause apparent -</div><div class=\"answer-line\">Ana screen / complement 1-2</div><div class=\"answer-line\">Rheum factor / crp</div><div class=\"answer-line\">Metabolic - uremia - renal function testing</div><div class=\"answer-line\">Malignant – lung Ca, if other symptoms or signs suggestive  - CT chest / abdomen as</div><div class=\"answer-line\">appropriate to suspected source.</div><div class=\"answer-line\"><strong>Passmark = 16/21 (adjust to /10) </strong></div><div class=\"answer-line\"><strong>(7.6/10) </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 21 year old aboriginal lady presents with a 24 hour history of a sore throat and\ndifficulty swallowing. She has a muffled voice and appears anxious.\nHer observations are:\n\nHR\n100\n\nBP\n110/65,\n\nRR\n\nSats\n98% RA\n\nTemp 39 Deg C.\nA lateral soft tissue neck X-ray is performed which is shown below. any way without previous permission","parts":[{"id":"a","label":"Part A","prompt":"What are the significant findings on this X-ray? (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 likely organisms that cause this condition in this patient.\n(4 marks)"},{"id":"c","label":"Part C","prompt":"List 5 immediate treatment priorities in the ED?\n(5 marks) any way without previous permission"}],"propPages":["asset:imgd5ba5d785cdd763c92"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Loss of cervical spine lordosis</div><div class=\"answer-line\"><strong>Normal prevertebral soft tissue spaces </strong></div><div class=\"answer-line\">No visible FB in airway</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Haemophilus influenzae b (Hib)</strong> (must have this for full marks)</div><div class=\"answer-line\">H.parainfluenzae</div><div class=\"answer-line\">Strep pneumonia</div><div class=\"answer-line\">Group A Strep (pyogenes)</div><div class=\"answer-line\">Staph aureus</div><div class=\"answer-line\">Atypical organisms (Mycoplasma)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Nurse in position of best comfort &amp; avoid distressing the patient</div><div class=\"answer-line\">Call for urgent assistance from Anaesthetics &amp; ENT</div><div class=\"answer-line\">Prepare to manage <strong>potential airway obstruction</strong> (difficult airway equipment</div><div class=\"answer-line\">including cric kit, but aim to intubate in OT with awake intubation unless acute</div><div class=\"answer-line\">deterioration)</div><div class=\"answer-line\">Analgesia – IV Paracetamol 1g, Morphine 0.1mg/kg titrated to analgesia but not</div><div class=\"answer-line\">drowsiness</div><div class=\"answer-line\">Antibiotics – Ceftriaxone (or Cefotaxime) 2g bd IV</div><div class=\"answer-line\"><strong>Passmark = 9/13 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(7/10) </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 2 year old boy presents to your ED with fever and drowsiness after being left\nunattended for 30mins in a locked vehicle.\nHer vitals signs are:\n\nHR\n150\n\nBP\n70/35\n\nTemp 41 C\n\nRR\n\nSats\n95%","parts":[{"id":"a","label":"Part A","prompt":"List 5 possible differential diagnoses.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List and justify 6 investigations you would perform in ED in this patient.\n(6 marks) any way without previous permission"},{"id":"c","label":"Part C","prompt":"Outline your approach for cooling this patient in the ED. (8 marks) any way without previous permission"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Heat stroke</strong> - environmental</div><div class=\"answer-line\"><strong>Sepsis </strong></div><div class=\"answer-line\"><strong>Drug ingestion</strong> – anticholinergic, sympathomimetic</div><div class=\"answer-line\">Meningitis</div><div class=\"answer-line\">UTI</div><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\">Thyroid storm</div><div class=\"answer-line\">Phaeochromocytoma</div><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">Metabolic causes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Evidence of multi-organ failure due to heat stroke </strong></div><div class=\"answer-line\">ABG – metabolic acidosis and respiratory alkalosis</div><div class=\"answer-line\">Electrolytes – hypokalaemia, hypocalcaemia, hypophosphataemia or</div><div class=\"answer-line\">hyperkalaemia – rhabdomyolysis</div><div class=\"answer-line\"><strong>Renal function</strong> – renal impairment in dehydration</div><div class=\"answer-line\"><strong>CK</strong> – increased in rhabdomyolysis</div><div class=\"answer-line\">Coags – abnormal in DIC</div><div class=\"answer-line\">Urinary myoglobin – present in rhabdomyolysis</div><div class=\"answer-line\"><strong>BSL</strong> – ensure normoglycaemia</div><div class=\"answer-line\"><strong>Septic screen</strong> – BC, urine, CXR +/- LP</div><div class=\"answer-line\">Urine drug screen – exclude ingestion as cause for hyperthermia</div><div class=\"answer-line\">ECG – may be arrhythmias if electrolyte abnormalities</div><div class=\"answer-line\">Metabolic screen – urine VMA, TFTs</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Close monitoring of skin and core temperature (rectal temp, IDC catheter)</div><div class=\"answer-line\">Remove clothing</div><div class=\"answer-line\"><strong>Active cooling to &lt; 40 degrees (give 2 options minimum) </strong></div><div class=\"answer-line\">Tepid water spray with fan cooling</div><div class=\"answer-line\">Ice water packs in axilla and groin</div><div class=\"answer-line\">Cooling blankets</div><div class=\"answer-line\">Cold IV fluids.</div><div class=\"answer-line\">May require RSI for sedation and paralysis if unsuccessful or unable to tolerate cooling.</div><div class=\"answer-line\">N.B No role for anti-pyretics in heat stroke.</div><div class=\"answer-line\"><strong>Passmark: 12 /19 ( adjust to  /10) </strong></div><div class=\"answer-line\"><strong>(6.5/10) </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 60 year old male is brought to your Emergency Department following an intentional\n• verdose. The ambulance crew report that he has ingested 25 Diltiazem XR 180mg\ntablets 5 hours ago.\nHis vital signs are:\n\nHR\n\nSats\n99% RA\n\nBP\n120/67\n\nTemp 36.7 oC\n\nRR\n\nBSL\n6.4 Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 4 factors associated with significant toxicity following calcium channel blocker\npoisoning? (4 Marks)"},{"id":"b","label":"Part B","prompt":"List 4 clinical features that may occur with significant calcium channel blocker\ntoxicity. (4 Marks) any way without previous permission 3- Several hours later the patient becomes agitated and clammy. He is being managed in a Resus area with non-invasive monitoring.\nHis vital signs now are:\n\nBP\n87/40\n\nHR\n\nSat\n93% on RA\n\nGCS 15/15\nList in a step-wise approach your management of this patient. (8 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Agent - diltiazem and verapamil associated with toxicity other CCBs do not cause</div><div class=\"answer-line\">significant toxicity</div><div class=\"answer-line\"><strong>Dose </strong>- x2-3 therapeutic dose can cause toxicity with XR prep and &gt;10x tablet</div><div class=\"answer-line\">ingestion likely to cause significant toxicity</div><div class=\"answer-line\"><strong>Co-ingestion</strong> of other cardiotoxic medication increases likelihood of significant</div><div class=\"answer-line\">toxicity</div><div class=\"answer-line\">Extremes of age - paediatric ingestion and elderly</div><div class=\"answer-line\">Presence of significant co-morbidities</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answers:</div><div class=\"answer-line\"><strong>Bradycardia (must have) </strong></div><div class=\"answer-line\"><strong>Hypotension (must have)</strong></div><div class=\"answer-line\">(Any of the following for 1 mark)</div><div class=\"answer-line\">AV block - 1st degree AV block</div><div class=\"answer-line\">Myocardia ischaemia</div><div class=\"answer-line\">Hyperglycaemia</div><div class=\"answer-line\">Pulmonary oedema</div><div class=\"answer-line\">Lactic acidosis</div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\"><strong>any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 2 month old baby presents to your ED with vomiting that has markedly\nincreased in number and volume in the last few days. He has been investigated in the community for cow’s milk protein allergy.\nHe was born at 3800g and now weighs 4300g.\nHis vital signs are:\n\nHR\n160\n\nBP\n60/40\n\nRR\n\nTemp\n36.5\n\nSats\n95% RA","parts":[{"id":"a","label":"Part A","prompt":"List 8 Differential Diagnoses for this presentation\n(8 marks) 2. A VBG is performed as part of his workup:\n\npH\n7.5\n\nPco2\n52.8\n\nPo2\n\nLac\n1.8\n\nHCo3\n\nHb\n116\n\nK\n1.8\n\nCl\n\nNa\n143 Ca 1.28\n\nGlucose"},{"id":"b","label":"Part B","prompt":"Describe 3 key abnormalities of the VBG and briefly comment on the possible\ncause of each. (6 marks) Metabolic abnormality Possible cause"},{"id":"c","label":"Part C","prompt":"What is the most likely diagnosis and explain why. (2 marks)"},{"id":"d","label":"Part D","prompt":"List and justify 3 further investigations required for this baby:\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answers:</div><div class=\"answer-line\">Sepsis: meningitis, UTI, gastroenteritis</div><div class=\"answer-line\">Metabolic – Inborn errors of metabolism</div><div class=\"answer-line\">Neurologic – Increased ICP</div><div class=\"answer-line\">Surgical</div><div class=\"answer-line\">Pyloric Stenosis</div><div class=\"answer-line\">Malrotation</div><div class=\"answer-line\">Intussusception</div><div class=\"answer-line\">Congenital cardiac abnormality</div><div class=\"answer-line\">Gastrooesophageal reflux</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answers:</div><div class=\"answer-line\"><strong>Severe Metabolic Alkalosis</strong> – vomiting resulted in loss of Hydrogen ions</div><div class=\"answer-line\">Respiratory Compensation – Expected CO2 46 is 52 therefore degree of Resp</div><div class=\"answer-line\">acidosis – mixed picture 2ndary to obtunded baby</div><div class=\"answer-line\"><strong>Hypokalaemic and hypochloraemic</strong> – loss of HCL with vomiting and</div><div class=\"answer-line\">intracellular exchange of cl with K to balance alkalosis</div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Pyloric Stenosis</strong> with the pathognomonic VBG of hypochloraemic, hypokalaemic</div><div class=\"answer-line\">metabolic alkalosis and the clinical picture of a significant increase in vomiting in</div><div class=\"answer-line\">a male baby in the appropriate age range.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">USS – confirm pyloric stenosis</div><div class=\"answer-line\">Septic workup – exclude sepsis</div><div class=\"answer-line\">AXR – rule out malrotation, obstruction</div><div class=\"answer-line\"><strong>Passmark = 16/22 (adjust to /10) </strong></div><div class=\"answer-line\"><strong>(7.5/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 75 year old male with a history of lung cancer is brought to your Emergency\nDepartment by ambulance complaining of worsening dyspnea for 2 days.\nHis vital signs are:\n\nHR\n120, SR\n\nBP\n95/55\n\nSaO2 88% on 4L Nasal prong oxygen\n\nTemp 37.5\n\nGCS\n13/15 (E4M5V4) A mobile chest X-ray is performed:","parts":[{"id":"a","label":"Part A","prompt":"List 3 relevant positive and 2 relevant negative findings on this CXR.\n(5 Marks) POSITIVES: Negatives:"},{"id":"b","label":"Part B","prompt":"In point form, describe the immediate management priorities in this case (3 Marks)"},{"id":"c","label":"Part C","prompt":"List the parameters needed to help distinguish between a transudate and an exudate pleural effusion in general? (4 marks)"}],"propPages":["asset:img5a576ab768487bcd7c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Marks)  4/5</div><div class=\"answer-line\">Positive:</div><div class=\"answer-line\">(Large) Pleural effusion</div><div class=\"answer-line\">Pneumothorax</div><div class=\"answer-line\">Tracheal deviation / mediastinum displaced to the left / radiological signs</div><div class=\"answer-line\">of tension</div><div class=\"answer-line\">?? 2 marks for hydropneumothorax</div><div class=\"answer-line\">NEGATIVES</div><div class=\"answer-line\">No surgical emphysema</div><div class=\"answer-line\">No oxygen tubing seen</div><div class=\"answer-line\">No visible mass / evidence of infection</div><div class=\"answer-line\">No bony lesions</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Identify any established limitations of care and manage appropriately</div><div class=\"answer-line\">Improve oxygenation – Additional oxygen via NRBM</div><div class=\"answer-line\">Decompression of pneumothorax + Formal ICC insertion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">an exudate pleural effusion in general?  - 3/4</div><div class=\"answer-line\">(4 Marks)</div><div class=\"answer-line\">Light’s Criteria – therefore tests needed are pleural fluid and serum LDH, pleural</div><div class=\"answer-line\">fluid and serum cholesterol, pleural fluid and serum albumin</div><div class=\"answer-line\"><strong>Passmark = 9/12 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(7.5/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 68 year male presents to ED with an episode of severe central chest pain and\npalpitations for the last 20 min. He has no prior medical history.\nHis vital signs include:\n\nGCS\n15/15\n\nBP\n110/66\n\nSpO2 95%\n\nRR\nHis ECG is reproduced for review:","parts":[{"id":"a","label":"Part A","prompt":"What is your interpretation of the ECG and state your evidence. (5 marks)"},{"id":"b","label":"Part B","prompt":"What is the likely anatomical origin of the abnormality? (1 mark)"},{"id":"c","label":"Part C","prompt":"What initial treatment would you give this patient in ED? INCLUDE DOSE AND ROUTE. (5 marks)"}],"propPages":["asset:imgd2d01a557d5772c5a2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">NW axis</div><div class=\"answer-line\">Concordance – esp V6 – negative</div><div class=\"answer-line\">Jeffersons notch</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Left VT – origin on left with electrical activity flowing to right</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">AND ROUTE.</div><div class=\"answer-line\">(5 marks) – 4/5</div><div class=\"answer-line\">2 priorities – Ischemia and VT</div><div class=\"answer-line\">Treat likely ischaemia</div><div class=\"answer-line\"><strong>Aspirin 300mg</strong> / morphine 2.5 mg IV / heparin 1000IU loading / GTN –</div><div class=\"answer-line\">sublingual</div><div class=\"answer-line\">Treat VT</div><div class=\"answer-line\"><strong>Amiodarone loading 300mg IV OR   DCCV with sedation </strong></div><div class=\"answer-line\">Correct electrolytes</div><div class=\"answer-line\"><strong>Passmark = 8/11 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(7.3/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 58 year old female is brought in to ED after being found by her husband\ncollapsed in the shower.\nHer vital signs on arrival are:\n\nHR\n\nBP\n180/120\n\nRR\n\nGCS\n8/15 (E2 V2 M4) She is immediately intubated prior to CT scan, which has been reproduced below:","parts":[{"id":"a","label":"Part A","prompt":"List the radiological abnormalities on the above scan. (4 marks)"},{"id":"b","label":"Part B","prompt":"List your immediate management priorities in this patient: (10 marks)"},{"id":"c","label":"Part C","prompt":"What criteria would you use to estimate this patient’s likely prognosis. (4 marks)"}],"propPages":["asset:img274831335103c05e24"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\"><strong>Extensive subarachnoid haemorrhage </strong></div><div class=\"answer-line\"><strong>Intra-ventricular haemorrhage</strong> – lateral ventricles, anterior horns, L)</div><div class=\"answer-line\">posterior horn</div><div class=\"answer-line\">No apparent hydrocephalus</div><div class=\"answer-line\">Evidence of cerebral oedema</div><div class=\"answer-line\">No midline shift</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Answers:</td></tr><tr><td colspan=\"2\"><strong>Instigate neuroprotective measures</strong>. (2 marks)</td></tr><tr><td colspan=\"2\">Maintain pCO2 30-35,</td></tr><tr><td colspan=\"2\">Maintain pO2 &gt; 80</td></tr><tr><td colspan=\"2\">Head up 30 degrees</td></tr><tr><td colspan=\"2\">Maintain normothermia</td></tr><tr><td colspan=\"2\">Maintain normoglycaemia</td></tr><tr><td colspan=\"2\">Ensure adequate sedation +/- paralysis (1 mark)</td></tr><tr><td colspan=\"2\">Morphine/Midazolam infusion</td></tr><tr><td colspan=\"2\"><strong>Treat Hypertension</strong>:  (1 mark for drug &amp; 1 for endpoint)</td></tr><tr><td colspan=\"2\">Invasive arterial BP monitoring</td></tr><tr><td colspan=\"2\">aim for SBP 160</td></tr><tr><td colspan=\"2\">GTN infusion, titrated to above endpoints</td></tr><tr><td colspan=\"2\">Hydralazine (5mg aliquats to 20 mg)</td></tr><tr><td colspan=\"2\">B-Blocker (Metoprolol 2.5mg aliquats to 20 mg or HR 60)</td></tr><tr><td colspan=\"2\">SNP infusion</td></tr><tr><td colspan=\"2\">Expedite <strong>Neurosurgery</strong> review (1 mark)</td></tr><tr><td>-</td><td>definitive Mx with early vs delayed clipping with CTA, 4-vessel</td></tr><tr><td colspan=\"2\">angio or MRA prior</td></tr><tr><td>-</td><td>ICP monitoring</td></tr><tr><td>-</td><td>EVD for monitoring/CSF drainage if developing hydrocephalus</td></tr><tr><td colspan=\"2\">Monitor for vasospasm:<strong> (Discrimator – if mention this get 2 marks)</strong></td></tr><tr><td colspan=\"2\">- Nimodipine Infusion (d/w neurosurgeons): start at 1mg/hr and</td></tr><tr><td colspan=\"2\">titrate up to 4 mg <strong> </strong></td></tr><tr><td colspan=\"2\">Supportive cares (2 marks)</td></tr><tr><td colspan=\"2\">IDC – hourly measures (DI or SIADH)</td></tr><tr><td colspan=\"2\"><strong>published in any way without previous permission</strong></td></tr><tr><td colspan=\"2\">The Prince Charles Hospital</td></tr><tr><td colspan=\"2\">NGT if intubated</td></tr><tr><td colspan=\"2\">Correct electrolyte abnormalities</td></tr><tr><td colspan=\"2\">Coagulation abnormalities</td></tr><tr><td colspan=\"2\">Maintenance fluid (isotonic)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Scoring System </strong>(Need to mention 1/3 scoring systems to pass)<strong> </strong></td></tr><tr><td>-</td><td>WFNS – Grade 4 (GCS 8, focal motor deficit)</td></tr><tr><td>-</td><td>Hunt &amp; Hess criteria – Grade 4-5</td></tr><tr><td>-</td><td>Fisher criteria – Grade 4</td></tr><tr><td colspan=\"2\">Likely <strong>poor prognosis</strong>, given low GCS with motor deficit and extensive CT</td></tr><tr><td colspan=\"2\">findings and age &gt; 50.</td></tr><tr><td><strong>Passmark = 11/18 (adjust to /10) </strong></td><td><strong>(6/10) </strong></td></tr><tr><td colspan=\"2\"><strong>published in any way without previous permission</strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 60 year old male presents to your ED with a 4 hour history of severe vertigo,\nwhich he describes as like the room is spinning. He has vomited multiple times and feels unsteady on his feet. His vital signs are within normal limits. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 4 peripheral & 4 central causes of vertigo.\n(8 marks)"},{"id":"b","label":"Part B","prompt":"List 5 features on examination that would be suggestive of central vertigo.\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List and justify 3 investigations that could be arranged from the ED to\ndistinguish between central and peripheral causes for vertigo. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>* Peripheral</td><td>* Central</td></tr><tr><td>BPPV</td><td>Posterior circulation CVA</td></tr><tr><td>Labyrinthitis</td><td>Cerebellar haemorrhage/infarction</td></tr><tr><td>Vestibular neuritis</td><td>Vertebrobasilar insufficiency</td></tr><tr><td>Meniere’s disease</td><td>Cerebellar tumour</td></tr><tr><td>Accoustic neuroma</td><td>MS</td></tr><tr><td>Cerebellopontine angle tumours</td><td>Lateral medullary syndrome</td></tr><tr><td>Barotrauma</td><td>Vertebral artery dissection</td></tr><tr><td colspan=\"2\">Ototoxicity</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vertical nystagmus</div><div class=\"answer-line\">Truncal ataxia</div><div class=\"answer-line\">Dysdiadochokinesis</div><div class=\"answer-line\">Romberg’s sign positive</div><div class=\"answer-line\">Dysarthria</div><div class=\"answer-line\">Limb weakness (focal neurology)</div><div class=\"answer-line\">Absence of a positional component (Negative Dix-Hallpike test)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CT Brain – Identify abnormalities of posterior fossa (eg bleed, tumour)</div><div class=\"answer-line\">MRI – Highly sensitive for posterior circulation CVA</div><div class=\"answer-line\">CTA Neck vessels – Identify vertebral artery dissection</div><div class=\"answer-line\"><strong>Passmark = 16/19 (adjust to /10) </strong></div><div class=\"answer-line\"><strong>(8.4/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 59 year old wheel chair bound paraplegic presents with chest pain and SOB.\nHe has a history of clipped Circle of Willis aneurysm which was done 6 years ago. He does not have a headache. A CTPA confirms he has a massive PE.\nHis vital signs are:\n\nGCS\n15/15\n\nHR\n114\n\nBP\n87/39\n\nRR\n\nSaO2 97% with O2 15 L/min via non re-breather mask\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"List 8 sequential steps in the management of this patient?\n(8 marks)"},{"id":"b","label":"Part B","prompt":"Briefly describe 3 ethical and medico-legal issues in this situation\n(3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">IV fluid bolus (N Saline 1-2L. Aim SBP 100)</div><div class=\"answer-line\">Central venous access and commence vasopressor if patient remains</div><div class=\"answer-line\">hypotensive (Noradrenaline infusion – Aim MAP 60-65)</div><div class=\"answer-line\">Organise bed side echo – look for elevated RV pressure and/or deviation</div><div class=\"answer-line\">of interventricular septum suggestion increased RV pressure</div><div class=\"answer-line\">Find further information of cerebral aneurysm – were there more than</div><div class=\"answer-line\">one aneurysm/ what interventions done</div><div class=\"answer-line\">Discuss with cardiothoracic surgery regarding suitability for surgical</div><div class=\"answer-line\">embolectomy (preferred treatment option)</div><div class=\"answer-line\">Discuss other treatment options with patient and family – thrombolysis</div><div class=\"answer-line\">with tenecteplase (if RV pressure is high) / anticoagulation with heparin</div><div class=\"answer-line\">(if RV pressure normal)</div><div class=\"answer-line\">If patient arrests – thrombolysis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Consent – challenging situation as previous h/o clipped aneurysm. May</div><div class=\"answer-line\">have difficulty in obtaining previous clinical information. Patient should</div><div class=\"answer-line\">be given information (risks and benefits) on each treatment modality for</div><div class=\"answer-line\">informed consent</div><div class=\"answer-line\">Possible thrombolysis of a patient with previous aneurysm without full</div><div class=\"answer-line\">clinical information</div><div class=\"answer-line\">Adequate documentation of discussions with patient and other specialties</div><div class=\"answer-line\"><strong>Passmark 8/11 (Adjust to  /10)  </strong></div><div class=\"answer-line\"><strong>(7.3/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 50 year old homeless alcoholic man has received 40% full thickness burns to\nhis torso and upper limbs after a fire in his bedding. He appears intoxicated currently and is struggling to breathe. There is a suggestion the fire may have been deliberately lit.\nHis vital signs are:\n\nHR\n110\n\nSats\n93% on 15L Oxygen\n\nRR\n\nBP\n100/55\n\nTemp 36.5\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"List 7 potential complications of this burn and describe the key management\n• ption for each.\n(14 marks) Complication 1: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 2: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 3: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 4: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 5: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 6: ------------------------------------------------------------------------------- Management option:-------------------------------------------------------------------------- Complication 7: ------------------------------------------------------------------------------- Management option:--------------------------------------------------------------------------"},{"id":"b","label":"Part B","prompt":"You are preparing to do an escharotomy of the torso when your resident asks whether the patient needs to consent to the procedure. List the principles of consent that apply in this situation. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>option for each.</td><td>(14 marks) - 10/14</td></tr><tr><td>Answer :</td><td></td></tr><tr><td>Airway burns with stridor – early intubation</td><td></td></tr><tr><td>Breathing – ventilation issues with restriction of chest wall movement–</td><td></td></tr><tr><td>escharotomy</td><td></td></tr><tr><td>Inhalational burns – oxygen and ventilatory support for ARDS – NIV with PEEP</td><td></td></tr><tr><td>Hypovolaemia – third spacing – rehydration using Parkland’s formula 4ml x kg</td><td></td></tr><tr><td>x % burn</td><td></td></tr><tr><td>Circumferential limb burns/Compartment syndrome – escharotomy</td><td></td></tr><tr><td>Rhabdo and ARF – 20ml/kg N saline to treat shock and then calculate burn</td><td></td></tr><tr><td>surface area and replace fluids over 48hrs.  Maintain UO.</td><td></td></tr><tr><td>Infection – cover burns and silver impregnated dressings for prevention of</td><td></td></tr><tr><td>infection</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">whether the patient needs to consent to the procedure.</div><div class=\"answer-line\">List the principles of consent that apply in this situation.  (3 marks)  - 2/3</div><div class=\"answer-line\">Answer 2</div><div class=\"answer-line\">Patient is critically unwell and will be <strong>unable</strong> <strong>to provide consent for this life-</strong></div><div class=\"answer-line\"><strong>saving procedure</strong>. He is unlikely to have capacity to consent given he is</div><div class=\"answer-line\">intoxicated, hypoxic and shocked and there is suspicion of self-harm.</div><div class=\"answer-line\">We will treat this patient’s life-threatening injuries under the principle of <strong>Duty </strong></div><div class=\"answer-line\"><strong>of Care</strong> (Guardianship Act) and proceed with treatment whilst attempting to</div><div class=\"answer-line\">notify next of kin or the Adult Guardian to inform them of the events.</div><div class=\"answer-line\"><strong>Documentation</strong> all discussions and decisions carefully in the medical record.</div><div class=\"answer-line\"><strong>Passmark = 12/17 (adjust to /10) </strong></div><div class=\"answer-line\"><strong>(7/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 40 year old female patient is brought to your tertiary Emergency Department\nfollowing a fall from 4 meters, where she landed heavily on her feet.\nHer vital signs are:\n\nGCS\n15/15\n\nRR\n\nHR\n100\n\nBP\n115/50\n\nSaO2 99% on 6L O2 via face mask\nHer pelvis X-ray is attached:","parts":[{"id":"a","label":"Part A","prompt":"Classify the radiological abnormality & state the findings that support this. (3 Marks)"},{"id":"b","label":"Part B","prompt":"List 5 possible complications of this injury in this patient. State how you would\nassess for these in the ED. Complete the table below. (10 marks)"},{"id":"c","label":"Part C","prompt":"List 2 alternate options for further management for this patient’s pelvic injury.\n(2 Marks)"},{"id":"d","label":"Part D","prompt":"List 5 factors which may affect your choice in the above management options.\n(5 Marks)"}],"propPages":["asset:img139a35fa02ee822832"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Vertical shear injury of pelvis (Malgaigne Fracture) consisting of:</div><div class=\"answer-line\">Superior and inferior pubic rami fractures</div><div class=\"answer-line\">Fracture of L iliac wing</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Arterial injury</td><td>Haemodynamic instability, blush on</td></tr><tr><td colspan=\"2\">CTA</td></tr><tr><td>Injury to genitalia</td><td>PV bleeding, perineal haematoma,</td></tr><tr><td colspan=\"2\">vaginal tears on PV exam</td></tr><tr><td>Urethral injury</td><td>Bloods at urethral meatus, inability to</td></tr><tr><td colspan=\"2\">insert IDC without resistance</td></tr><tr><td>Bladder injury</td><td>Retrograde CT urethrogram with</td></tr><tr><td colspan=\"2\">constrast extravasation</td></tr><tr><td>Lumbosacral plexus nerve injury</td><td>Paraesthesias, weakness of lower limb</td></tr><tr><td>Rectal injury – compound fracture</td><td>PR bleeding, bony fragments of PR</td></tr><tr><td colspan=\"2\">exam</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Interventional Radiology – for embolization of potential arterial injury</div><div class=\"answer-line\">Operating theatre for surgical management/pelvic packing/external fixation</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Availability of interventional radiology resources &amp; staff vs theatre resources &amp;</div><div class=\"answer-line\">staff</div><div class=\"answer-line\">(- eg time of day, location, hospital resources)</div><div class=\"answer-line\">Haemodynamic stability of patient – better to go to OT if ongoing instability</div><div class=\"answer-line\"><strong>Associated injuries of patient</strong> – better to go to OT if associated <strong>chest or abdo </strong></div><div class=\"answer-line\"><strong>injuries</strong></div><div class=\"answer-line\"><strong>Results of FAST scan</strong> – positive FAST for intraabdominal bleeding should go to</div><div class=\"answer-line\">OT</div><div class=\"answer-line\">Presence of blush on CTA of pelvis – may benefit from interventional radiology &amp;</div><div class=\"answer-line\">embolization</div><div class=\"answer-line\"><strong>Passmark = 16/20 (adjust /10)  </strong></div><div class=\"answer-line\"><strong>(8/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 35 year old woman presents to your ED with a short duration of illness\ncharacterised by fevers, headache and photophobia.\nHer vital signs on arrival are:\n\nHR\n\nBP\n120/60\n\nRR\n\nSats\n96% RA\n\nTemp 39\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"List 5 key examination findings that may support a diagnosis of\nmeningitis. (5 marks)"},{"id":"b","label":"Part B","prompt":"Lumber puncture is required as part of this patient’s workup, Describe in a stepwise fashion this procedure (in point form) (7 marks) 3. The results of your LP are as follows. CSF:\n\nWCC\n700 (predominance polymorphs) RCC Protein 1.0\n\nGlucose\n2.0 (Normal range > 2.5 mmol) Gram stain +ve for bacteria Describe the key features and interpret (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 additional tests that need to be performed on the obtained CSF:\n(3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">meningitis</div><div class=\"answer-line\">(5 marks) – 4/5</div><div class=\"answer-line\">Answer 1:</div><div class=\"answer-line\">Shock with Cardiovascular collapse</div><div class=\"answer-line\">ALOC with delirium and coma</div><div class=\"answer-line\">Signs of meningism - Neck stiffness - Kernigs sign, Brudinski’s sign</div><div class=\"answer-line\">Focal neurological signs or CN lesions – 15%</div><div class=\"answer-line\">Rash and arthritis particularly meningococcal if a petechial/purpuric rash</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">stepwise fashion this procedure (in point form)</div><div class=\"answer-line\">(7 marks) – 6/7</div><div class=\"answer-line\">Answer 2:</div><div class=\"answer-line\">Preparation for the procedure – patient prep including <strong>consent</strong> and</div><div class=\"answer-line\">consideration of sedation.</div><div class=\"answer-line\">Mark landmarks – sup aspect of Iliac crest</div><div class=\"answer-line\">Preparation of equipment – LP tray including 2 needles, anaesthetic 2%</div><div class=\"answer-line\">lignocaine 5ml, chlorhexidine for the site, drape, gloves, gown and mask and</div><div class=\"answer-line\">tubes for collection labelled and numbered</div><div class=\"answer-line\">Preparation of staff – surgical assistant to catch CSF etc</div><div class=\"answer-line\">Position the patient either seated or L lateral curled up</div><div class=\"answer-line\"><strong>Aseptic technique</strong> – glove, gown and prep skin</div><div class=\"answer-line\">Local anaesthetic 5-10ml</div><div class=\"answer-line\">Insertion 22-25g spinal needle midline cephalad bevel parallel 20-30degrees and</div><div class=\"answer-line\">wait for two loss of resistance</div><div class=\"answer-line\">ICP measurement if indicated</div><div class=\"answer-line\">Collection CSF 10 drops three sequential tubes</div><div class=\"answer-line\">Replace stylet</div><div class=\"answer-line\">Apply dressing and ambulate</div><div class=\"answer-line\">Send labelled specimens for testing</div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">CSF:</td></tr><tr><td>WCC</td><td>700  (predominance polymorphs)</td></tr><tr><td>RCC</td><td>15</td></tr><tr><td>Protein</td><td>1.0</td></tr><tr><td>Glucose</td><td>2.0 (normal ranges?)</td></tr><tr><td>Gram stain</td><td>+ve for bacteria</td></tr><tr><td>Describe the key features and interpret</td><td>(3 marks) - 2/3</td></tr><tr><td colspan=\"2\"><strong>WCC &gt; 500</strong> predominance of polymorphs increased <strong>likelihood that it is </strong></td></tr><tr><td colspan=\"2\"><strong>bacterial meningitis. </strong></td></tr><tr><td colspan=\"2\"><strong>Protein raised and glucose low</strong> supportive of bacterial meningitis also</td></tr><tr><td colspan=\"2\">But also <strong>could be partially treated meningitis or could be viral meningitis in </strong></td></tr><tr><td colspan=\"2\"><strong>particular enterovirus which can mimic this picture</strong></td></tr><tr><td colspan=\"2\">4.  List 3 additional tests that need to be performed on the obtained CSF:</td></tr><tr><td colspan=\"2\">(3 marks) – 2/3</td></tr><tr><td colspan=\"2\">Culture</td></tr><tr><td colspan=\"2\">Meningococcal, Pneumococcal PCRs</td></tr><tr><td colspan=\"2\">Viral PCRs – (enterovirus, HSV)</td></tr><tr><td><strong>Passmark = 14/18 (adjust to /10) </strong></td><td><strong>(7.5/10) </strong></td></tr><tr><td colspan=\"2\"><strong>published in any way without previous permission</strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 50 year-old woman is brought into your Emergency Department by ambulance\ncomplaining of palpitations for the last 30 minutes. She takes no regular medications and is unaware of any significant medical history. Her pre-hospital vital signs are:\n\nGCS\n15/15\n\nBP\n110/60\n\nSpO2 98% on RA\n\nTemp 36.2\nHer pre-hospital ECG is provided: Questions:","parts":[{"id":"a","label":"Part A","prompt":"What is the diagnosis and list 4 supportive ECG finding: (5 marks)"},{"id":"b","label":"Part B","prompt":"In point form, List your management steps. For any drugs used, please provide the dose and route of administration. (8 marks)"}],"propPages":["asset:imgb4ccf69418320134cc"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Suggests <strong>rapid AF</strong> <strong>with likely accessory pathway, eg WPW </strong></div><div class=\"answer-line\">Irregularly irregular broad complex (but will aceept narrow – it’s borderline)</div><div class=\"answer-line\">tachycardia (QRS widened, or borderline (approx 100ms)</div><div class=\"answer-line\">Rate up to 300 bpm in parts</div><div class=\"answer-line\">Delta waves visible in lead V3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Apply defibrillation pads - Monitor for degeneration into VF</div><div class=\"answer-line\"><strong>Synchronised DC cardioversion</strong> 100-150 J</div><div class=\"answer-line\">- Consent for DC cardioversion</div><div class=\"answer-line\">- Analgesia: Fentanyl 0.5-1 mcg/Kg IV</div><div class=\"answer-line\">- Sedation: Propofol 0.5 mg/kg IV titrated to effect</div><div class=\"answer-line\">Ensure restoration of sinus rhythm and repeat ECG to look for accessory</div><div class=\"answer-line\">pathway</div><div class=\"answer-line\"><strong>OR Chemical Cardioversion </strong></div><div class=\"answer-line\"><strong>- Avoid drugs that act on AV node – Ca channel blockers, digoxin, b blocker </strong></div><div class=\"answer-line\">- IV amiodarone 300 mg or Procainamide 15mg/kg IV, IV Flecainide</div><div class=\"answer-line\">Cardiology referral/input/follow-up</div><div class=\"answer-line\"><strong>Passmark = 8/13 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(6/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 32 year old , 28 week gestation female is brought in to your tertiary Emergency\nDepartment following a Motor Vehicle Accident.\nHer vital signs are as follows:\n\nHR\n110\n\nBP\n90/60\n\nGCS\n\nTemp 36.8\n\nSaO2 97% on room air\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"In your initial ED assessment of this patient, list 5 conditions specific to trauma in pregnancy that you would be trying to exclude? (5 Marks)"},{"id":"b","label":"Part B","prompt":"Briefly outline 5 potential uses for ultrasound in the ED in this patient and\nhow pregnancy may limit its utility. (4 Marks)"},{"id":"c","label":"Part C","prompt":"She starts to show painless bright red heavy PV bleeding just after her arrival in the ED. Outline your initial 6 steps in the management of this patient in the ED. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Fetal distress</div><div class=\"answer-line\">Placental abruption</div><div class=\"answer-line\">Amniotic fluid embolism</div><div class=\"answer-line\">Uterine injury/rupture</div><div class=\"answer-line\">Laceration of placenta or cord</div><div class=\"answer-line\">Premature rupture of membranes</div><div class=\"answer-line\">Premature labour</div><div class=\"answer-line\">Foetomaternal haemorrhage</div><div class=\"answer-line\">Direct fetal injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fetal heart beat – does not negate the need for CTG</div><div class=\"answer-line\">FAST exam – Accuracy limited by gravid uterus, positive scan still of use</div><div class=\"answer-line\">Assessment for abruption – May miss up to 50%, poor Sensitivity</div><div class=\"answer-line\">Pneumothorax – May be more accurate than CXR, can help identify site for</div><div class=\"answer-line\">insertion of ICC</div><div class=\"answer-line\">(6 marks) 4/6</div><div class=\"answer-line\"><strong>Resuscitate the mother</strong> if signs of shock – IV fluid boluses aiming for MAP &gt; 60</div><div class=\"answer-line\"><strong>Check fetal heartrate</strong> with USS +/- CTG if available</div><div class=\"answer-line\">Urgently notify with <strong>O&amp;G</strong> and theatre re possible placental abruption &amp; possible</div><div class=\"answer-line\">need for urgent delivery of fetus</div><div class=\"answer-line\">Large bore IV Access &amp; bloods sent for Xmatch</div><div class=\"answer-line\"><strong>Urgent USS</strong> to assess for fetal wellbeing, abruption, uterine rupture, placenta</div><div class=\"answer-line\">praevia</div><div class=\"answer-line\">Speculum examination by O&amp;G team to assess causes of bleeding</div><div class=\"answer-line\">Steroids for fetal lung maturation (Betamethasone 12mg)</div><div class=\"answer-line\"><strong>Passmark ( 11/15)  (adjust to 10) </strong></div><div class=\"answer-line\"><strong>(7.3/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 45 year old man presents to the ED with a painful Left shoulder after falling\n• nto his outstretched arm. He is lying most comfortably on a bed with his arm\nabducted above his head.","parts":[{"id":"a","label":"Part A","prompt":"What do the images show? (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 complications associated with this injury\n(4 marks)"},{"id":"c","label":"Part C","prompt":"Briefly explain how you would treat this injury (4 marks)"}],"propPages":["asset:img9d12e4db7245147a3c","asset:img22b6c0aa8c5a76aad3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left inferior glenohumeral joint dislocation + greater tuberosity #.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Brachial plexus injury</div><div class=\"answer-line\">Rotator cuff injury or shoulder instability</div><div class=\"answer-line\">Vascular injury</div><div class=\"answer-line\">Associated fracture of acromion, glenoid</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">MUST mention to give analgesia &amp; dose</div><div class=\"answer-line\">Pre/post neurovascular assessment</div><div class=\"answer-line\">Informed consent</div><div class=\"answer-line\">Reduction under PS and will require pre-sedation risk assessment,</div><div class=\"answer-line\">Mention one technique (eg axial traction)</div><div class=\"answer-line\"><strong>Passmark – 7/10 </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 19 year-old man presents to the ED with 12 hours of unilateral testicular\nswelling and pain. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses for this presentation. For each diagnosis, list two\nkey features (either historical or on examination) that may help distinguish that diagnosis. (12 marks) Diagnosis Features 2- You phone the surgical registrar on call to request that he review the patient urgently in ED. The surgical registrar states he will not come to review the patient until you have the results of an ultrasound of the testes. Briefly describe your approach to this situation. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Features</td><td></td></tr><tr><td>Testicular torsion</td><td>History: sudden onset</td></tr><tr><td>(Pass/fail)</td><td>Exam: Transverse lie, loss of cremasteric reflex</td></tr><tr><td>Epididymo-orchitis</td><td>History: Known STD, dysuria, discharge</td></tr><tr><td>Exam: Warm hemiscrotum, temp</td><td></td></tr><tr><td>Torted appendix</td><td>History: may have local trauma</td></tr><tr><td>testis</td><td>Exam: Blue dot sign</td></tr><tr><td>Direct inguinal hernia</td><td>History: Known hernia, post valsalva</td></tr><tr><td>Exam: Cough impulse, bowel sounds on auscultation</td><td></td></tr><tr><td>2- You phone the surgical registrar on call to request that he review the patient</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 23 year old woman with anorexia nervosa presents to your ED with weakness\nand vomiting for the past 2 weeks. She weighs 35kg.\nHer vital signs are:\n\nBP\n80/40\n\nRR\n\nTemp 34.9 C\n\nSats\n95% on RA","parts":[{"id":"a","label":"Part A","prompt":"Her ECG is reproduced for review. What is the most likely diagnosis and provide supporting evidence. (5 marks) -"},{"id":"b","label":"Part B","prompt":"Describe 6 management steps for the above patient including any drugs\nrequired: (6Marks)"},{"id":"c","label":"Part C","prompt":"List the potential ethical and legal pitfalls that could be anticipated in the management of this patient: (2 marks)"},{"id":"d","label":"Part D","prompt":"List 6 common physical symptoms that a patient with anorexia nervosa may\npresent with to the ED. For each list one potential underlying cause. (12 marks) Symptoms Reasons"}],"propPages":["asset:img8c92c54e5a7154ecd4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">provide supporting evidence.</div><div class=\"answer-line\">(5 marks) - 4/5</div><div class=\"answer-line\">Answer:</div><div class=\"answer-line\"><strong>Bradycardia</strong> - Rate 50</div><div class=\"answer-line\"><strong>Long QT interval </strong></div><div class=\"answer-line\">T wave flattening and inversion</div><div class=\"answer-line\">U waves</div><div class=\"answer-line\">Characteristic of <strong>hypokalaemia</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">required: - 5/6</div><div class=\"answer-line\">Multi-disciplinary team approach including medical, psychiatric and social</div><div class=\"answer-line\">worker.</div><div class=\"answer-line\">Treat shock with 20ml/kg   normal saline , aim for Systolic &gt; 90 and MAP &gt;65</div><div class=\"answer-line\">and Urine output 0.5 ml/kg/hr</div><div class=\"answer-line\">Identify and treat hypoglycaemia with 50 ml of 50% Dextrose</div><div class=\"answer-line\">Electrolyte correction: K and Mg IV supplement</div><div class=\"answer-line\">Treat hypothermia with passive rewarming (Bear hugger)</div><div class=\"answer-line\">IF HR remains low with hypotension: consider atropine 300 mcg boluses and</div><div class=\"answer-line\">start atropine infusion</div><div class=\"answer-line\">Thiamine 100 mg TDS and multivitamin supplement.</div><div class=\"answer-line\">Will require admission under Psych and Medicine in order to commence feeding</div><div class=\"answer-line\">once shock has been managed. Monitor for refeeding syndrome.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patient might refuse the above treatment or lack insight into her condition,</div><div class=\"answer-line\">therefore <strong>lacking capacity</strong> to consent.</div><div class=\"answer-line\">Under <strong>duty of care</strong> principle, this patient could be kept in hospital to receive the</div><div class=\"answer-line\">above treatment even if she is unable to consent.</div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div><div class=\"answer-line\">Patient may try to leave requiring escalation of restraint. (Verbal de-escalation</div><div class=\"answer-line\">with input from her NOK, family and Psych team , next step will be</div><div class=\"answer-line\">pharmacological restrain as last resource.)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>present with to the ED. For each list one potential underlying cause.</td><td></td></tr><tr><td>(12 marks) – 8/12</td><td></td></tr><tr><td>Answer:</td><td></td></tr><tr><td>Chest pain - Cardiomyopathy, arrythmias secondary to electrolytes</td><td></td></tr><tr><td>Palpitations - brady/tachycardia, arrhythmias</td><td></td></tr><tr><td>Constipation – dehydration, hypocalcaemia</td><td></td></tr><tr><td>Abdo pain - pancreatitis post binge, secondary to ileus</td><td></td></tr><tr><td>Collapse or syncope – hypoglycaemia, hypocalcaemia, anaemia</td><td></td></tr><tr><td>Fractures – secondary to osteopenia</td><td></td></tr><tr><td>Weakness – electrolyte abn hypokalaemia, hypocalcaemia, hypoglycaemia,</td><td></td></tr><tr><td>peripheral neuropathy, hypothyroidism</td><td></td></tr><tr><td><strong>Passmark = 18/25 (adjust to /10) </strong></td><td><strong>(7.2/10) </strong></td></tr><tr><td><strong>published in any way without previous permission</strong></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"An 18 month old boy is brought into your ED by his parents with a rash to his\nface. The rash has been there for a few days and has been worsening. He has had a reduced oral intake and mum states that he has ‘felt hot’. He is fully immunised and has a background history of atopy.\nHis vital signs are:\n\nGCS\n15/15\n\nHR\n130 bpm\nCRT <2sec\n\nTemp 37.8\nBelow is a picture of the rash: Questions:","parts":[{"id":"a","label":"Part A","prompt":"Describe the features of the rash (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? List two other alternative diagnoses. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 management priorities for this child\n(4 marks)"}],"propPages":["asset:imge4809b0584ad868053"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Multiple vesicles with erythematous base</div><div class=\"answer-line\">Coalescing around right cheek</div><div class=\"answer-line\">Crusted</div><div class=\"answer-line\">Lower lip involved, some lesions close to eye</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\"><strong>Eczema herpeticum</strong> (most likely diagnosis)</div><div class=\"answer-line\"><strong>Impetigo</strong></div><div class=\"answer-line\">Chicken pox</div><div class=\"answer-line\">Hand foot and mouth with secondary bacterial infection</div><div class=\"answer-line\">Steven-Johnsons syndrome</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Analgesia – sensible choice with doses</div><div class=\"answer-line\">Treat skin condition</div><div class=\"answer-line\">o Acyclovir 5-10mg/kg IV</div><div class=\"answer-line\">o Flucloxacillin 50 mg/kg IV</div><div class=\"answer-line\">Look for complications – shock, hypovolaemia, sepsis, eye, meningitis,</div><div class=\"answer-line\">encephalitis</div><div class=\"answer-line\">Admit for treatment, analgesia +/- rehydration</div><div class=\"answer-line\"><strong>Passmark = 8/11 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(8/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 30 year old woman with a history of IVDU has presented to your ED with a\npresenting complaint of anxiety and states she cannot see out of her right eye. On further questioning, the visual loss has been there for a number of hours and is painless. Eye examination is normal externally with no redness of the eye and normal eye movements. She can count fingers only on the right eye with 6/60 vision. Fundoscopy reveals the below picture. Questions:","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis and give justification from the photo and the stem (4 marks)"},{"id":"b","label":"Part B","prompt":"In point form, list your management priorities of this patient’s presentation: (4 marks)"},{"id":"c","label":"Part C","prompt":"In the table below, list 8 other common causes of acute visual loss (unrelated to this patient) and give one distinguishing historical feature of each (16 marks) Causes of visual loss Historical features"}],"propPages":["asset:img797d7398828578fa69"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>CRAO </strong>because pale optic disc, <strong>white oedema</strong> of infarction and <strong>cherry </strong></div><div class=\"answer-line\"><strong>red spot</strong> and <strong>also the rapidity of onset of visual loss, the </strong></div><div class=\"answer-line\"><strong>completeness of it and the risk factor of IVDU therefore embolism</strong>.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ophthalmology referral</div><div class=\"answer-line\">Anticoagulation with Heparin</div><div class=\"answer-line\">Localised pressure to eye</div><div class=\"answer-line\">Identify source of emboli</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>– 10/16</td><td></td></tr><tr><td>Answers:</td><td></td></tr><tr><td>Glaucoma</td><td>Pain</td></tr><tr><td>Retinal vein occlusion</td><td>Painless onset minutes not complete</td></tr><tr><td>loss assoc hyperviscosity, DM etc</td><td></td></tr><tr><td>Retinal detachment</td><td>Shade over eye slow onset flashes and</td></tr><tr><td>floaters</td><td></td></tr><tr><td>Optic neuritis</td><td>Over days, colour vision progresses,</td></tr><tr><td>assoc pain, APD</td><td></td></tr><tr><td>Vitreous haemorrhage</td><td>Assoc trauma and diabetes and</td></tr><tr><td>detachment – sudden painless vision</td><td></td></tr><tr><td>loss</td><td></td></tr><tr><td>Optic N chiasm compression</td><td>Often incomplete fields other</td></tr><tr><td>symptoms tumour</td><td></td></tr><tr><td>Uveitis</td><td>Pain and redness and decreased VA</td></tr><tr><td>Toxic and metabolic</td><td>Hx of methanol etc – bilateral loss</td></tr><tr><td>neuropathies</td><td></td></tr><tr><td>Amaourosis fugax and TIA and</td><td>Temporary</td></tr><tr><td>migraine</td><td></td></tr><tr><td><strong>Passmark = 15/24 (adjust to /10) </strong></td><td><strong>(6.2/10) </strong></td></tr><tr><td><strong>published in any way without previous permission</strong></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 70 year old female presents to ED with a history of ‘falling over at the shops’\n• ne hour previously. She has a history of previous ischemic heart disease. She\nadmits that recently she has become severely short of breath when walking to\nthe bus stop 20 meters from her home. Her current medications include aspirin\nand atenolol.\nHer vital signs are:\n\nBP\n96/66\n\nSpO2 92% in room air\n\nTemp 37 C\n\nRR\nShe has bipedal pitting oedema to her ankles and bibasal crepitations on lung auscultation. Her ECG has been reproduced for review:","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities on her ECG. (2 marks)"},{"id":"b","label":"Part B","prompt":"What is the significance of these findings? (2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 causes contributing to the findings on the ECG.\n(4 marks)"},{"id":"d","label":"Part D","prompt":"What definitive cardiac investigations does this patient need and state why? (3 marks)"}],"propPages":["asset:imgd16f417cddd4c008a5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">RBBB and LAFB/L axis deviation  (Bifascicular block)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Complete heart block may have occurred, with intermittent block of the</div><div class=\"answer-line\">posterior fascicle with resultant syncope.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ischaemic heart disease</div><div class=\"answer-line\">Rate related LBBB with complete heart block</div><div class=\"answer-line\">CCF</div><div class=\"answer-line\">Outflow tract obstruction - HT/Aortic stenosis</div><div class=\"answer-line\">Infiltrative/Degenerative</div><div class=\"answer-line\">Inflammatory - SLE</div><div class=\"answer-line\">Medication related – B Blockade, Digoxin</div><div class=\"answer-line\">(Any 4 of these for 1 mark each)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">(3 issues to address – heart failure, arrhythmia and need for pacemaker,</div><div class=\"answer-line\">underlying ischemia  2/3 of these to pass)</div><div class=\"answer-line\">Test for cardiac ischaemia - Stress Echo / MPS/ Angiogram</div><div class=\"answer-line\">Test for arrhythmias - Holter monitor, Electrophysiological study</div><div class=\"answer-line\">Tests for underlying cardiac structure &amp; function - Echo</div><div class=\"answer-line\"><strong>Passmark = 9/11 (adjust to /10)  </strong></div><div class=\"answer-line\"><strong>(9/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"An 8 year old boy is brought into your ED by his mother after having fallen off\nthe trampoline onto his out-stretched arm. He is crying, with an obvious deformity to his arm. There are no other injuries. He has had an urgent X-ray arranged by the triage nurse.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities in the X-ray above. (4 marks)"},{"id":"b","label":"Part B","prompt":"List three analgesic options you could use in this case, including doses and routes of administration. (6 marks)"},{"id":"c","label":"Part C","prompt":"List three complications of this injury which should be sought in the ED and the clinical features associated with these complications. (6 marks) Complications Clinical features"}],"propPages":["asset:img59b369c679ee7420a2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answer<em><strong>: </strong></em></div><div class=\"answer-line\">Monteggia fracture (can use eponymous name but should also describe</div><div class=\"answer-line\">abnormalities that make up a Monteggia fracture)</div><div class=\"answer-line\">Spiral fracture of midshaft of ulna</div><div class=\"answer-line\">Dislocation of proximal radius</div><div class=\"answer-line\">Ulnar fracture has significant displacement and angulation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Answer:</div><div class=\"answer-line\">Fentanyl 1-1.5 mcg/kg IN</div><div class=\"answer-line\">Morphine 0.05-0.1mg/kg IV</div><div class=\"answer-line\">Oral analgesia (Paracetamol 15mg/kg or Ibuprofen 10mg/hr)</div><div class=\"answer-line\">Will accept any third option that implies analgesia to facilitate <strong>splinting</strong></div><div class=\"answer-line\">and urgent reduction in OT, eg Entonox</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Answer:</td></tr><tr><td>Radial nerve injury</td><td>Paraesthesia in dorsum of hand and 3.5 fingers</td></tr><tr><td colspan=\"2\">Wrist drop</td></tr><tr><td>Compartment syndrome</td><td>Refractory pain, distal paraesthesia/numbness</td></tr><tr><td colspan=\"2\">(less likely to be in nerve distribution)</td></tr><tr><td>Compound fracture</td><td>Open wound, bone on show</td></tr><tr><td><strong>Passmark = 13/16  (adjust to /10) </strong></td><td><strong>(8/10) </strong></td></tr><tr><td colspan=\"2\"><strong>published in any way without previous permission</strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 63 year old male patient presents to your ED complaining of fever of 38\ndegrees measured at home today. He last had chemotherapy for Non-Hodgkin\nlymphoma 8 days ago. He has an indwelling central venous catheter in situ. He\nhas no other symptoms.\nHis vital signs are:\n\nHR 110\n\nBP 100/80\n\nSaO2 98% Room air\n\nGCS 15\n\nTemp 38.6\nHis initial Full Blood Count is as follows:\n\nHb 97 g/dL\nMCV 85\nPlt 12\n\nWCC 0.4\nNeut 0.02\nQuestions:","parts":[{"id":"a","label":"Part A","prompt":"List & briefly justify 5 additional tests you would perform in the ED in this case. (10 Marks)"},{"id":"b","label":"Part B","prompt":"State your antibiotic choice/s and doses in this case where no source can be identified. The patient has no known allergies and normal renal function. (3 Marks) 3- The patient’s blood pressure drops and is unresponsive to fluid resuscitation. He requires inotropes to maintain an adequate MAP and local practice is to use central venous access. His indwelling line is now unable to be successfully accessed.\nOutline 6 strategies you would use to minimize potential complications of central\nvenous line insertion in this patient. (6 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bloods cultures – peripheral and from indwelling catheter</div><div class=\"answer-line\">Urine m/c/s - not dipstick as may be false negative leuk esterase if neutropenic</div><div class=\"answer-line\">CXR</div><div class=\"answer-line\">Sputum m/c/s – if productive cough or SOB</div><div class=\"answer-line\">Culture of any other sites of likely infection eg skin, wound, port site</div><div class=\"answer-line\">CT brain - if confused or ALOC</div><div class=\"answer-line\">LP - if concerns for meningitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Piperacillin + Tazobactam 4.5g tds IV</div><div class=\"answer-line\">Gentamycin 5mg/kg IV daily</div><div class=\"answer-line\">Vancomycin 1g bd IV (as indwelling line insitu)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"Your junior doctor has just reviewed a 61 year old man who has re-presented to the ED requesting further medications to treat his anxiety and depression. This is his third presentation to the ED with a 3 month of dyspnoea, weakness and\n\nweight loss.\nHe had most recently been discharged by another ED registrar 2 days ago with a prescription for Diazepam. The junior doctor was concerned that the patient appeared pale and did routine bloods.\nHis observations are:\n\nHR 80 bpm,\n\nRR 22 bpm,\n\nSats 98% RA\n\nBP 130/58 mmHg,\n\nTemp 37.8 Deg C\nThese are the results of the FBC: Differential Result Normal range\n\nWCC\n2.9 4.0 - 11.0 x 109/L\n\nHb\n135 - 180 g/L Plt 140 - 400 x 109/L RBC 2.04 4.5 - 6.0 x 1012/L MCV 80 - 100 f/L Neut 0.12 2.00 - 8.00 x 109/L Lymph 1.44 0.10 - 4.00 x 109/L Mono 0.15 0.1 - 1.00 x 109/L Questions:","parts":[{"id":"a","label":"Part A","prompt":"What is the significant finding on his FBC? (1 mark)"},{"id":"b","label":"Part B","prompt":"List 5 possible causes of the above finding\n(5 marks)"},{"id":"c","label":"Part C","prompt":"List 5 investigations that would assist with your diagnosis in the ED and\nbriefly state why. (10 marks)"},{"id":"d","label":"Part D","prompt":"Your director requests you to provide feedback to the Registrar regarding this case. List the steps involved in this process. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pancytopenia/Marrow failure with all cell lines involved.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Marrow failure (aplastic anaemia, viral illness, toxins)</div><div class=\"answer-line\">Marrow</div><div class=\"answer-line\">infiltration</div><div class=\"answer-line\">(leukaemia,</div><div class=\"answer-line\">lymphoma,</div><div class=\"answer-line\">myelofibrosis,</div><div class=\"answer-line\">myeloma,</div><div class=\"answer-line\">megaloblastic anaemia)</div><div class=\"answer-line\">Drugs/Toxins (chemotherapeutic agents, immunosuppressants)</div><div class=\"answer-line\">(Any of these is acceptable for 1 mark each)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Blood smear/films looking for blast cells (Must have this to get 1 mark)</div><div class=\"answer-line\">CXR – looking for malignancy</div><div class=\"answer-line\">USS/CT Abdo – possible malignancy, splenomegaly</div><div class=\"answer-line\">Coags – looking for coagulopathy</div><div class=\"answer-line\">Viral serology – (EBV, CMV, HIV)</div><div class=\"answer-line\">B12/Folate levels – megaloblastic anaemia</div><div class=\"answer-line\">LFTS – looking for liver disease as a cause</div><div class=\"answer-line\">(N.B Bone marrow aspirate would not be considered an “ED test” for this</div><div class=\"answer-line\">condition)</div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div><div class=\"answer-line\">The Prince Charles Hospital</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Gather information on case from other sources (chart, GP letters, interview staff)</div><div class=\"answer-line\">Contact Registrar and arrange to meet to discuss the case</div><div class=\"answer-line\">Discuss case in open, nonjudgmental manner with Registrar</div><div class=\"answer-line\">Discuss cognitive error &amp; premature closure with diagnosis</div><div class=\"answer-line\">Direct additional learning required from this case</div><div class=\"answer-line\">Refer case to departmental M&amp;M process, suggest Registrar to be involved in</div><div class=\"answer-line\">presenting the case.</div><div class=\"answer-line\"><strong>Passmark = 17/21 (adjust to /10) </strong></div><div class=\"answer-line\"><strong>(8/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"You receive a phone-call from the nurse at triage. There is a 34 year-old woman at triage who has just walked in stating she feels ‘feverish and generally unwell’. The patient returned from Liberia in Western Africa five days ago where she was visiting family and she is concerned she may have the Ebola virus. Questions:","parts":[{"id":"a","label":"Part A","prompt":"What immediate steps will you take to assess this patient safely in your ED? (5 marks)"},{"id":"b","label":"Part B","prompt":"List five differential diagnoses for this patient and for each one name the investigation of choice to exclude or confirm the diagnosis. (10 marks) DDX Investigations (to exclude or confirm Dx) 3- The patient is appropriately managed in your department. The triage nurse states to you that she felt under-prepared for dealing with this specific patient. List three strategies you could employ to further educate the department. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Answers:</div><div class=\"answer-line\">Avoid direct physical contact with patient</div><div class=\"answer-line\"><strong>Triage patient in a designated area away from other patients </strong></div><div class=\"answer-line\">Dedicated medical and nursing staff member to assess pt</div><div class=\"answer-line\"><strong>PPE</strong> for all staff dealing with pt</div><div class=\"answer-line\">Patient to enter ED via decontamination area (if necessary) and then to negative</div><div class=\"answer-line\">pressure isolation room</div><div class=\"answer-line\">Minimise patient-staff interactions</div><div class=\"answer-line\">Any tests to be carefully labelled as potentially hazardous</div><div class=\"answer-line\"><strong>Notify relevant people – Infectious Diseases physician/Med Super/Public </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Answers:</td><td></td></tr><tr><td>Ebola haemorrhagic virus</td><td>Serum for PCR or antigen testing</td></tr><tr><td>Malaria</td><td>Thick and thin films for direct malarial parasite</td></tr><tr><td>identification</td><td></td></tr><tr><td>Dengue fever</td><td>Serology for Dengue PCR</td></tr><tr><td>Bacteraemia</td><td>Blood culture</td></tr><tr><td>Typhoid</td><td>Blood culture; Serum for antibody testing</td></tr><tr><td>Influenza</td><td>Nasopharyngeal aspirate for viral PCR</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 57 year old homeless man is brought to ED with shortness of breath. He has a\nhistory of alcohol and drug abuse, with frequent ED presentations for violent altercations whilst intoxicated.\nHis vital signs include:\n\nHR\n135\n\nBP\n180/110\n\nTemp\n37.8 C\n\nSpO2\n90 % in room air\n\nRR\nHe is agitated, aggressive and diaphoretic. He has dilated pupils bilaterally, but no focal neurology. He has mild epistaxis from excoriated, inflamed nares. He appears cachectic. He has impetigo in multiple sites. His CXR is reproduced for review.","parts":[{"id":"a","label":"Part A","prompt":"Describe the significant abnormalities on this CXR. (2 marks)"},{"id":"b","label":"Part B","prompt":"List 4 important negative findings on this CXR.\n(4 marks)"},{"id":"c","label":"Part C","prompt":"List 5 conditions in your differential diagnosis.\n(5marks)"},{"id":"d","label":"Part D","prompt":"List 5 investigations this patient will require to further refine the diagnosis\nand provide your justification for each. (10 marks)"}],"propPages":["asset:imgc143f5e15046027bbd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Alveolar opacities – patchy alveolar <strong>opacification</strong></div><div class=\"answer-line\">predominantly in the <strong>bilateral</strong>, perihilar upper lobes.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">No hilar lymphadenopathy</div><div class=\"answer-line\">Cardiac silhouette normal/Normal CTR</div><div class=\"answer-line\">No Effusions</div><div class=\"answer-line\">No rib fractures or pneumothorax</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Alveolar hemorrhage (secondary to underlying lung disease, vasculitis</td></tr><tr><td colspan=\"2\">coagulopathy or drug use – cocaine abuse)</td></tr><tr><td colspan=\"2\">Acute Pulmonary oedema – (non cardiogenic or Cardiogenic pulmonary oedema)</td></tr><tr><td colspan=\"2\">Infection</td></tr><tr><td>-</td><td>Bacterial (? Staph), viral or atypical pneumonia,</td></tr><tr><td>-</td><td>Immunocompromised host infections such as PCP, TB</td></tr><tr><td>-</td><td>Aspiration pneumonia secondary to respiratory depression and</td></tr><tr><td colspan=\"2\">obtundation &amp; alcohol abuse</td></tr><tr><td colspan=\"2\">Traumatic lung contusion</td></tr><tr><td colspan=\"2\">Septic emboli from cardiac valvular disease / infective endocarditis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>The Prince Charles Hospital</td><td></td></tr><tr><td>CT Chest (High resolution +/- CTPA) - delineate and identify the nature of lesion</td><td></td></tr><tr><td>/ extent &amp; exclude trauma as a cause</td><td></td></tr><tr><td>Blood culture – identify organisms in sepsis, diagnosis of IE</td><td></td></tr><tr><td>Sputum m/c/s &amp; PCR – for bacteria pathogens (strep / staph)</td><td></td></tr><tr><td>Viral swabs/NPA – confirm or exclude viral pathogens as cause</td><td></td></tr><tr><td>ECG – assess for myocardial ischaemia as cause for CCF</td><td></td></tr><tr><td>Echo – assess LVEF for cardiomyopathy or valve lesions for infective</td><td></td></tr><tr><td>endocarditis</td><td></td></tr><tr><td>Urine drug screen – assess for drugs of abuse such as cocaine as cause for</td><td></td></tr><tr><td>CCF/haemorrhage</td><td></td></tr><tr><td>Screening for HIV, TB</td><td></td></tr><tr><td>Vasculitis screen – (Wegeners / Goodpastures) – SLE / RH factor / ANCA’s / ANA</td><td></td></tr><tr><td><strong>Passmark = 16/21 (adjust to /10) </strong></td><td><strong>(7.5/10) </strong></td></tr><tr><td><strong>published in any way without previous permission</strong></td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":28,"title":"","stemText":"A 40 year old known schizophrenic patient presents to your ED by ambulance on\nan involuntary order. He had been behaving erratically at a train station. Whilst waiting to be seen he absconds from the ED and is unable to be located by ED staff. Questions:","parts":[{"id":"a","label":"Part A","prompt":"Outline your 5 immediate steps in managing this situation\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 6 features that would make this patient at high risk of self harm.\n(6 marks) 3- A few hours later the patient is returned to the ED by police. On arrival he is behaving aggressively and is resisting being moved into a treatment cubicle.\nList 3 options for chemical restraint, including doses and endpoints of treatment.\n(7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Security to search premises</div><div class=\"answer-line\">Attempt to contact patient by his listed mobile phone.</div><div class=\"answer-line\">Notify police that patient has absconded &amp; request welfare check at listed</div><div class=\"answer-line\">address</div><div class=\"answer-line\">Notify NOK that patient has absconded &amp; ask them to bring him back to ED if</div><div class=\"answer-line\">they have contact with him.</div><div class=\"answer-line\">Notify psychiatric unit that patient on involuntary order has absconded</div><div class=\"answer-line\">Document attempts to locate patient in chart</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Recent cessation of medications</div><div class=\"answer-line\">Active auditory hallucinations or delusions</div><div class=\"answer-line\">Recent suicidal ideation</div><div class=\"answer-line\">Past suicidal ideation or attempts</div><div class=\"answer-line\">Recent depressive symptoms</div><div class=\"answer-line\">Concurrent drug abuse</div><div class=\"answer-line\">Lack of social supports</div><div class=\"answer-line\">Loss to follow up with psychiatric care</div><div class=\"answer-line\">High number of psychiatric hospitalisations</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":29,"title":"","stemText":"You are the day shift ED consultant arriving to receive departmental handover at 8am. Your ED has 12 acute monitored beds and a SSU that has 6 beds. The senior nurse informs you that there are 5 patients admitted to the SSU by the ED Night Registrar that all have ongoing abnormal vital signs. She is concerned about the suitability of these patients for short stay care. Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 8 steps in your approach to managing this issue.\n(8 marks)"},{"id":"b","label":"Part B","prompt":"In light of this incident, your director asks you to develop a set of exclusion criteria for the Short Stay Unit. List your criteria. (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Assign the next most senior doctor to attend SSU and coordinate review </strong></div><div class=\"answer-line\"><strong>these patients urgently. </strong></div><div class=\"answer-line\">Arrange to move any unstable patients to a higher area of care (eg Resus)</div><div class=\"answer-line\">Take handover for rest of the department.</div><div class=\"answer-line\">Assign handovers &amp; prioritise assessment of new patients to day staff.</div><div class=\"answer-line\">Proceed to SSU after handover to review SSU patients with Night Registrar &amp;</div><div class=\"answer-line\">discuss management.</div><div class=\"answer-line\">Arrange to <strong>debrief with Night Registrar</strong> about the shift and any difficulties at</div><div class=\"answer-line\">another time.</div><div class=\"answer-line\"><strong>Identify any critical errors that have occurred</strong> and ensure key learning has</div><div class=\"answer-line\">been addressed in these cases with treating doctor.</div><div class=\"answer-line\">Notify your director of the situation.</div><div class=\"answer-line\">Refer any cases where patient safety was compromised for review through</div><div class=\"answer-line\">departmental M&amp;M process.</div><div class=\"answer-line\">Review any current SSU guidelines.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Unstable haemodynamic status</div><div class=\"answer-line\">Need for ongoing cardiac monitoring</div><div class=\"answer-line\">GCS &lt; 14</div><div class=\"answer-line\">LOS likely to exceed 24 hours</div><div class=\"answer-line\">Patients requiring intensive 1:1 nursing</div><div class=\"answer-line\">Care better managed by inpatient unit (eg complex medical or surgical patients)</div><div class=\"answer-line\">Patients without clear diagnosis or treatment plan</div><div class=\"answer-line\">Patients posing risk to staff (eg psychotic, violent, forensic history)</div><div class=\"answer-line\">Elderly patients who are unable to mobilise</div><div class=\"answer-line\"><strong>Passmark: ( 11/16) Adjust to /10 </strong></div><div class=\"answer-line\"><strong>(6.8/10) </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":30,"title":"","stemText":"A 45 year old man presents to your rural ED with pain, weakness and\nparaesthesia in the left arm that is worsened by abducting his arm. On examination he has weak pulse on that side.\nHis vital signs are:\n\nHR\n110 irregular\n\nBP\n130/80\n\nRR\n\nSats\n96% on RA Afebrile Questions:","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnosis for this presentation\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 5 investigations and justify each one of them:\n(5 marks)"},{"id":"c","label":"Part C","prompt":"Your investigation suggested that the cause related to his arrhythmia, in point form, list your management priorities (5 marks) GOOD LUCK"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Embolic – from AF</div><div class=\"answer-line\">Thrombotic</div><div class=\"answer-line\">Traumatic – penetrating injury</div><div class=\"answer-line\">Iatrogenic – IVC or IV drug arterial injection</div><div class=\"answer-line\">Aortic dissection extending to subclavian artery</div><div class=\"answer-line\">Neuro – spinal SAH</div><div class=\"answer-line\">Thoracic outlet syndrome</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>FBC –</td><td>polycythaemia – increased risk of thrombus</td></tr><tr><td>ECG –</td><td>AF as a risk factor for embolism</td></tr><tr><td colspan=\"2\">Doppler US – pulse presence or absence and quantify flow</td></tr><tr><td colspan=\"2\">US upper arm – thrombus or embolism</td></tr><tr><td>CXR –</td><td>cervical ribs in thoracic outlet syndrome</td></tr><tr><td colspan=\"2\">CT neck/thorax – SAH and cervical ribs/thoracic outlet</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">point form, list your management priorities</div><div class=\"answer-line\">(5 marks)  3/5</div><div class=\"answer-line\">Medical specific management –</div><div class=\"answer-line\">Heparin bolus  5000IU then infusion</div><div class=\"answer-line\">Correct any underlying contributors – dehydration etc</div><div class=\"answer-line\">Rate control B blocker etc,</div><div class=\"answer-line\">Analgesia – morphine 5-10mg</div><div class=\"answer-line\">Surgical consultation to direct definitive management (will need</div><div class=\"answer-line\">subspecialty input)– rapid revascularisation required within 8 hours.</div><div class=\"answer-line\">Either embolectomy or catheter directed thrombolysis.</div><div class=\"answer-line\">Organise retrieval to subspecialty services</div><div class=\"answer-line\"><strong>Passmark (11/15) adjust to /10  </strong></div><div class=\"answer-line\"><strong>(7.3/10) </strong></div><div class=\"answer-line\"><strong>Over all passmark:  220/300 </strong></div><div class=\"answer-line\"><strong>published in any way without previous permission</strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
